"""Chapter 2 — Programming Environment: High-Level, Bytecode, and Machine Code.

Demonstrates:
- High-level Python source code
- Intermediate bytecode executed by the Python Virtual Machine (PVM)
- Binary machine representation (0s and 1s / transistor states)

Run:
    python modules/module_01_fundamentals/examples/ch02_environment_levels.py
"""

import dis
import io
from contextlib import redirect_stdout


def add_high_level(a: int, b: int) -> int:
    """Simple high-level function used to inspect generated bytecode."""
    return a + b


def inspect_bytecode() -> str:
    """Capture the CPython bytecode instructions for `add_high_level`."""
    buffer = io.StringIO()
    with redirect_stdout(buffer):
        dis.dis(add_high_level)
    return buffer.getvalue()


def text_to_binary(text: str) -> str:
    """Convert each character into its 8-bit binary representation."""
    # Reverse Engineering:
    # ord(ch) reads the numeric Unicode/ASCII code point of `ch`;
    # format(..., '08b') formats that integer as an 8-bit binary string.
    return " ".join(format(ord(ch), "08b") for ch in text)


def get_layers_and_ides() -> dict[str, list[str]]:
    """Summarize architectural layers, language levels, and popular IDEs."""
    return {
        "layers": [
            "Frontend (user-facing interface)",
            "Backend (business logic, databases, servers)",
        ],
        "language_levels": [
            "High-level: Python (human-readable syntax)",
            "Low-level: Bytecode (.pyc) and Assembly (closer to CPU)",
            "Machine language: Binary (0s and 1s / transistors)",
        ],
        "ides": ["PyCharm", "Anaconda", "VS Code", "Jupyter", "Terminal / REPL"],
    }


def main() -> None:
    print("=== Chapter 2: Layers and Programming Environment ===\n")

    info = get_layers_and_ides()
    print("Application layers:")
    for item in info["layers"]:
        print(f"  - {item}")

    print("\nLanguage hierarchy:")
    for item in info["language_levels"]:
        print(f"  - {item}")

    print("\nPopular IDEs and tools:")
    print("  " + ", ".join(info["ides"]))

    print("\n--- Bytecode Reverse Engineering for `add_high_level(a, b)` ---")
    print(inspect_bytecode().strip())

    sample = "Py"
    print(f"\nBinary representation (machine level) for '{sample}':")
    print(f"  {text_to_binary(sample)}")


if __name__ == "__main__":
    main()
